export function translateRecipeText(
  id: string,
  locale: "it" | "en" | "pl" | "es" | "hi",
  fallback: RecipeLocaleText,
): RecipeLocaleText {
  if (locale === "it") return fallback;
  const block = RECIPE_TRANSLATIONS[id];
  if (!block) return fallback;
  return block[locale] ?? fallback;
}
